import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/getisord/getisord_2023_gas.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Define the neighborhood relationships
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate combined Gas values
combined_gas_values = {}
for borough in data['borough'].unique():
    combined_gas_values[borough] = data.loc[data['borough'] == borough, 'Gas_value'].sum() + sum(data.loc[data['borough'] == neighbor, 'Gas_value'] for neighbor in neighborhoods.get(borough, []))

# Apply the Getis-Ord Gi* method
mean_gas_value = data['Gas_value'].mean()
std_gas_value = data['Gas_value'].std()
z_scores = {}
for borough in data['borough'].unique():
    if np.isnan(combined_gas_values[borough]):
        z_scores[borough] = np.nan
    else:
        z_scores[borough] = (combined_gas_values[borough] - mean_gas_value) / std_gas_value

# Identify statistically significant hot and cold spots
hot_spots = {}
cold_spots = {}
for borough, z_score in z_scores.items():
    if np.abs(z_score) > 1.96:  # 95% confidence
        if z_score > 0:
            hot_spots[borough] = z_score
        else:
            cold_spots[borough] = z_score

# Report results
data_points_used = len(data['borough'].unique())
results = []
for borough in hot_spots:
    results.append(f"{borough} (HOT, Gi*={hot_spots[borough]})")
for borough in cold_spots:
    results.append(f"{borough} (COLD, Gi*={cold_spots[borough]})")
if not results:
    results.append("none")
print(f"data_points_used = {data_points_used}")
print(f"FINAL ANSWER: {', '.join(results)}")
